<?= $this->extend('layouts/app') ?><?= $this->section('content') ?>
<?php $teamInitials = static function (string $name): string { $name = trim($name); if ($name === '') return '—'; $parts = preg_split('/\s+/', $name) ?: []; $parts = array_values(array_filter($parts, static fn(string $part): bool => $part !== '')); return count($parts) >= 2 ? strtoupper(substr($parts[0], 0, 1) . substr($parts[1], 0, 1)) : strtoupper(substr($name, 0, 2)); }; $teamMarkStyle = static function (string $name): string { $seed = strtolower(trim($name)); $hue = hexdec(substr(md5($seed !== '' ? $seed : 'tbd'), 0, 4)) % 360; return '--tt-team-hue: ' . $hue . ';'; }; ?>
<div class="page-head"><div><h1>Teams</h1><p>Manage participating ISF teams.</p></div><button class="btn primary" data-modal="team-modal"><?= ui_icon('plus') ?><span>Add Team</span></button></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>#</th><th>Avatar</th><th>Team Name</th><th>Code</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($teams as $i => $team): ?><?php $avatarPath = trim((string) ($team['avatar_path'] ?? '')); ?><tr><td><?= $i + 1 ?></td><td><span class="tt-bracket-team-mark" style="<?= esc($teamMarkStyle((string) $team['name']), 'attr') ?>" aria-hidden="true"><?php if ($avatarPath !== ''): ?><img src="<?= esc(base_url($avatarPath), 'attr') ?>" loading="lazy" decoding="async" width="24" height="24" alt=""><?php else: ?><?= esc($teamInitials((string) $team['name'])) ?><?php endif; ?></span></td><td><b><?= esc($team['name']) ?></b></td><td><span class="badge neutral"><?= esc($team['code']) ?></span></td><td><div class="row-actions"><button class="btn tiny" data-modal="team-edit-<?= (int) $team['id'] ?>"><?= ui_icon('pencil') ?><span>Edit</span></button><form method="post" action="<?= site_url('teams/'.$team['id'].'/delete') ?>" data-confirm="Remove this team? This is only allowed when it is not used by schedules or results."><?= csrf_field() ?><button class="btn tiny danger"><?= ui_icon('trash') ?><span>Delete</span></button></form></div></td></tr><?php endforeach; ?>
<?php if (!$teams): ?><tr><td colspan="5" class="empty">No teams yet.</td></tr><?php endif; ?>
</tbody></table></div></section>
<?php foreach ($teams as $team): ?><?php $avatarPath = trim((string) ($team['avatar_path'] ?? '')); ?><dialog id="team-edit-<?= (int) $team['id'] ?>"><form method="post" action="<?= site_url('teams/'.$team['id'].'/update') ?>" class="modal-card" enctype="multipart/form-data"><?= csrf_field() ?><div class="modal-head"><h2>Edit Team</h2><button type="button" data-close aria-label="Close"><?= ui_icon('x') ?></button></div><label>Team Name<input name="name" required maxlength="150" value="<?= esc($team['name']) ?>"></label><label>Team Code<input name="code" required maxlength="30" value="<?= esc($team['code']) ?>"></label><label>Team Avatar<input type="file" name="avatar" accept="image/webp"><small class="muted">WebP only, max 512 KB; square recommended.</small></label><div class="form-note"><span class="tt-bracket-team-mark" style="<?= esc($teamMarkStyle((string) $team['name']), 'attr') ?>" aria-hidden="true"><?php if ($avatarPath !== ''): ?><img src="<?= esc(base_url($avatarPath), 'attr') ?>" loading="lazy" decoding="async" width="24" height="24" alt=""><?php else: ?><?= esc($teamInitials((string) $team['name'])) ?><?php endif; ?></span><label class="check"><input type="checkbox" name="remove_avatar" value="1"> Remove current avatar</label></div><button class="btn primary full"><?= ui_icon('save') ?><span>Save Changes</span></button></form></dialog><?php endforeach; ?>
<dialog id="team-modal"><form method="post" action="<?= site_url('teams') ?>" class="modal-card" enctype="multipart/form-data"><?= csrf_field() ?><div class="modal-head"><h2>Add Team</h2><button type="button" data-close aria-label="Close"><?= ui_icon('x') ?></button></div><label>Team Name<input name="name" required maxlength="150" placeholder="e.g. CBA Lions"></label><label>Team Code<input name="code" required maxlength="30" placeholder="e.g. CBA"></label><label>Team Avatar<input type="file" name="avatar" accept="image/webp"><small class="muted">WebP only, max 512 KB; square recommended.</small></label><button class="btn primary full"><?= ui_icon('save') ?><span>Save Team</span></button></form></dialog>
<?= $this->endSection() ?>
